import { readFileSync } from 'node:fs';
const hook = readFileSync('./src/useCounter.js', 'utf-8');
const comp = readFileSync('./src/Counter.jsx', 'utf-8');
// 残留 stale 模式：useEffect 空依赖数组 + interval 回调读取 count
const staleEmptyDeps = /useEffect\(\(\)\s*=>[\s\S]{0,300}setInterval[\s\S]{0,300}\bcount\b[\s\S]{0,100}\},\s*\[\]\);/.test(hook);
// 修复充分条件（任一典型方案）：依赖数组含 [count] / setCount 函数式更新 / useRef
const staleFixed = /},\s*\[count\]\);/.test(hook) || /setCount\((c|prev|n)\s*=>/.test(hook) || /useRef/.test(hook);
// 定时器 cleanup 恢复
const intervalCleaned = /clearInterval\(timer\)/.test(hook);
// resize 事件监听 cleanup 恢复
const resizeCleaned = /removeEventListener/.test(comp);
if ((staleEmptyDeps && !staleFixed) || !intervalCleaned || !resizeCleaned) { console.error('NOT_ALL_FIXED'); process.exit(1); }
